from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
FS = ROOT / "Minify" / "core" / "fs.py"
D2PFX = ROOT / "Minify" / "browsers" / "d2pfx" / "data.py"
FS_TEST = ROOT / "tests" / "test_fs_security.py"
D2PFX_TEST = ROOT / "tests" / "test_d2pfx_security.py"

fs = FS.read_text(encoding="utf-8")
if "import tempfile\n" not in fs:
    fs = fs.replace("import subprocess\n", "import subprocess\nimport tempfile\n", 1)
start = fs.index("def download_file(")
end = fs.index("\n\ndef extract_archive", start)
new_download = '''def download_file(\n    url: str,\n    target_path: str,\n    progress_tag: Optional[str] = None,\n    max_bytes: int | None = security.ARCHIVE_MAX_FILE_BYTES,\n) -> bool:\n    \"\"\"Download to a temporary file with bounded size and request timeouts.\"\"\"\n    response = None\n    temporary = None\n    try:\n        if max_bytes is not None and max_bytes < 1:\n            raise ValueError(\"max_bytes must be positive or None\")\n\n        response = requests.get(url, stream=True, timeout=(10, 60))\n        response.raise_for_status()\n        try:\n            total_size = int(response.headers.get(\"content-length\", 0) or 0)\n        except (TypeError, ValueError):\n            total_size = 0\n        if max_bytes is not None and total_size > max_bytes:\n            raise ValueError(f\"Download exceeds the {max_bytes}-byte safety limit.\")\n\n        block_size = 8192\n        downloaded = 0\n        last_report_time = 0\n        parent = os.path.dirname(os.path.abspath(target_path)) or os.getcwd()\n        os.makedirs(parent, exist_ok=True)\n        fd, temporary = tempfile.mkstemp(prefix=\".minify-download-\", dir=parent)\n\n        with os.fdopen(fd, \"wb\") as f:\n            for chunk in response.iter_content(chunk_size=block_size):\n                if not chunk:\n                    continue\n                downloaded += len(chunk)\n                if max_bytes is not None and downloaded > max_bytes:\n                    raise ValueError(f\"Download exceeds the {max_bytes}-byte safety limit.\")\n                f.write(chunk)\n                if progress_tag:\n                    current_time = time.time()\n                    if current_time - last_report_time >= 0.1:\n                        downloaded_mb = downloaded / (1024 * 1024)\n                        total_size_mb = total_size / (1024 * 1024)\n                        if total_size > 0:\n                            dpg.set_value(\n                                progress_tag,\n                                f\"Downloading: {downloaded_mb:.2f}/{total_size_mb:.2f} MB\",\n                            )\n                        else:\n                            dpg.set_value(progress_tag, f\"Downloading: {downloaded_mb:.2f} MB\")\n                        last_report_time = current_time\n\n        os.replace(temporary, target_path)\n        temporary = None\n\n        if progress_tag:\n            downloaded_mb = downloaded / (1024 * 1024)\n            total_size_mb = total_size / (1024 * 1024)\n            if total_size > 0:\n                dpg.set_value(progress_tag, f\"Downloading: {downloaded_mb:.2f}/{total_size_mb:.2f} MB\")\n            else:\n                dpg.set_value(progress_tag, f\"Downloading: {downloaded_mb:.2f} MB\")\n        return True\n    except Exception as e:\n        if temporary:\n            try:\n                os.remove(temporary)\n            except FileNotFoundError:\n                pass\n        output.add_text(f\"Failed to open {target_path}: {e}\", msg_type=\"error\")\n        return False\n    finally:\n        if response is not None:\n            with utils.try_pass():\n                response.close()\n'''
fs = fs[:start] + new_download + fs[end:]
FS.write_text(fs, encoding="utf-8")

data = D2PFX.read_text(encoding="utf-8")
data = data.replace("import gzip\nimport io\n", "", 1)
if "import tempfile\n" not in data:
    data = data.replace("import os\n", "import os\nimport tempfile\n", 1)
data = data.replace("from core import base, config, fs", "from core import base, config, fs, security", 1)
start = data.index("    def fetch_gz_json(")
end = data.index("\n    def refresh", start)
new_fetch = '''    def fetch_gz_json(self, filename, force_refresh=False):\n        local_path = os.path.join(self.cache_dir, filename.replace(\".gz\", \"\"))\n        gz_url = f\"{BASE_URL}data/{filename}\"\n\n        if not force_refresh and os.path.exists(local_path):\n            try:\n                if os.path.getsize(local_path) > security.D2PFX_MAX_MANIFEST_BYTES:\n                    raise ValueError(\"Cached D2PFX catalogue exceeds the safety limit.\")\n                with open(local_path, \"r\", encoding=\"utf-8\") as f:\n                    cached = json.load(f)\n                if not isinstance(cached, dict):\n                    raise ValueError(\"Cached D2PFX catalogue must be a JSON object.\")\n                return cached\n            except Exception:\n                pass\n\n        response = None\n        try:\n            response = requests.get(gz_url, stream=True, timeout=(10, 30))\n            if response.status_code == 200:\n                compressed = bytearray()\n                for chunk in response.iter_content(chunk_size=64 * 1024):\n                    if not chunk:\n                        continue\n                    compressed.extend(chunk)\n                    if len(compressed) > security.D2PFX_MAX_MANIFEST_BYTES:\n                        raise ValueError(\"Compressed D2PFX catalogue exceeds the safety limit.\")\n\n                decoded = security.bounded_zlib_decompress(\n                    bytes(compressed),\n                    max_output=security.D2PFX_MAX_MANIFEST_BYTES,\n                )\n                data = json.loads(decoded.decode(\"utf-8\"))\n                if not isinstance(data, dict):\n                    raise ValueError(\"D2PFX catalogue must be a JSON object.\")\n\n                fd, temporary = tempfile.mkstemp(prefix=\".d2pfx-catalogue-\", suffix=\".json\", dir=self.cache_dir)\n                try:\n                    with os.fdopen(fd, \"w\", encoding=\"utf-8\") as out:\n                        json.dump(data, out, indent=2)\n                    os.replace(temporary, local_path)\n                except Exception:\n                    try:\n                        os.remove(temporary)\n                    except FileNotFoundError:\n                        pass\n                    raise\n                return data\n        except Exception as e:\n            print(f\"Error fetching {filename}: {e}\")\n        finally:\n            if response is not None:\n                try:\n                    response.close()\n                except Exception:\n                    pass\n\n        return None\n'''
data = data[:start] + new_fetch + data[end:]
D2PFX.write_text(data, encoding="utf-8")

tests = FS_TEST.read_text(encoding="utf-8")
tests = tests.replace("from core.fs import extract_archive", "from core.fs import download_file, extract_archive", 1)
if "test_download_file_rejects_declared_oversize" not in tests:
    tests += '''\n\nclass _FakeResponse:\n    def __init__(self, chunks, content_length=0):\n        self._chunks = chunks\n        self.headers = {\"content-length\": str(content_length)} if content_length else {}\n        self.status_code = 200\n        self.closed = False\n\n    def raise_for_status(self):\n        return None\n\n    def iter_content(self, chunk_size=8192):\n        yield from self._chunks\n\n    def close(self):\n        self.closed = True\n\n\n@patch(\"core.fs.output.add_text\")\n@patch(\"core.fs.requests.get\")\ndef test_download_file_rejects_declared_oversize(mock_get, mock_add_text, tmp_path):\n    response = _FakeResponse([b\"ignored\"], content_length=101)\n    mock_get.return_value = response\n    target = tmp_path / \"payload.bin\"\n\n    assert download_file(\"https://example.invalid/payload\", str(target), max_bytes=100) is False\n    assert not target.exists()\n    assert response.closed is True\n    assert mock_get.call_args.kwargs[\"timeout\"] == (10, 60)\n    assert \"safety limit\" in mock_add_text.call_args.args[0]\n\n\n@patch(\"core.fs.output.add_text\")\n@patch(\"core.fs.requests.get\")\ndef test_download_file_aborts_stream_over_limit_without_replacing_target(mock_get, mock_add_text, tmp_path):\n    response = _FakeResponse([b\"12345\", b\"67890\", b\"X\"])\n    mock_get.return_value = response\n    target = tmp_path / \"payload.bin\"\n    target.write_bytes(b\"existing\")\n\n    assert download_file(\"https://example.invalid/payload\", str(target), max_bytes=10) is False\n    assert target.read_bytes() == b\"existing\"\n    assert not list(tmp_path.glob(\".minify-download-*\"))\n    assert response.closed is True\n    assert \"safety limit\" in mock_add_text.call_args.args[0]\n'''
FS_TEST.write_text(tests, encoding="utf-8")

if not D2PFX_TEST.exists():
    D2PFX_TEST.write_text('''import gzip\nimport json\nimport os\nimport sys\nfrom unittest.mock import patch\n\nsys.path.insert(0, os.path.abspath(os.path.join(os.path.dirname(__file__), \"../Minify\")))\n\nfrom browsers.d2pfx import data as d2pfx_data\n\n\nclass _FakeResponse:\n    def __init__(self, payload, status_code=200):\n        self.payload = payload\n        self.status_code = status_code\n        self.closed = False\n\n    def iter_content(self, chunk_size=65536):\n        for index in range(0, len(self.payload), chunk_size):\n            yield self.payload[index : index + chunk_size]\n\n    def close(self):\n        self.closed = True\n\n\ndef _manager(monkeypatch, tmp_path):\n    cache = tmp_path / \"d2pfx\"\n    previews = cache / \"previews\"\n    monkeypatch.setattr(d2pfx_data, \"CACHE_DIR\", str(cache))\n    monkeypatch.setattr(d2pfx_data, \"PREVIEWS_CACHE_DIR\", str(previews))\n    return d2pfx_data.DataManager()\n\n\n@patch(\"browsers.d2pfx.data.requests.get\")\ndef test_d2pfx_catalogue_uses_bounded_stream_and_atomic_cache(mock_get, monkeypatch, tmp_path):\n    manager = _manager(monkeypatch, tmp_path)\n    payload = gzip.compress(json.dumps({\"modsData\": {\"terrain\": []}}).encode())\n    response = _FakeResponse(payload)\n    mock_get.return_value = response\n\n    result = manager.fetch_gz_json(\"mods.json.gz\", force_refresh=True)\n\n    assert result == {\"modsData\": {\"terrain\": []}}\n    assert response.closed is True\n    assert mock_get.call_args.kwargs[\"stream\"] is True\n    assert mock_get.call_args.kwargs[\"timeout\"] == (10, 30)\n    assert json.loads((tmp_path / \"d2pfx\" / \"mods.json\").read_text()) == result\n    assert not list((tmp_path / \"d2pfx\").glob(\".d2pfx-catalogue-*\"))\n\n\n@patch(\"browsers.d2pfx.data.requests.get\")\ndef test_d2pfx_catalogue_rejects_decompression_over_limit(mock_get, monkeypatch, tmp_path):\n    manager = _manager(monkeypatch, tmp_path)\n    monkeypatch.setattr(d2pfx_data.security, \"D2PFX_MAX_MANIFEST_BYTES\", 64)\n    payload = gzip.compress(json.dumps({\"modsData\": {\"x\": \"A\" * 256}}).encode())\n    response = _FakeResponse(payload)\n    mock_get.return_value = response\n\n    assert manager.fetch_gz_json(\"mods.json.gz\", force_refresh=True) is None\n    assert response.closed is True\n    assert not (tmp_path / \"d2pfx\" / \"mods.json\").exists()\n\n\ndef test_d2pfx_rejects_oversized_cached_catalogue(monkeypatch, tmp_path):\n    manager = _manager(monkeypatch, tmp_path)\n    monkeypatch.setattr(d2pfx_data.security, \"D2PFX_MAX_MANIFEST_BYTES\", 32)\n    cached = tmp_path / \"d2pfx\" / \"mods.json\"\n    cached.write_text(\"{\" + \" \\"x\\\": \\"\" + \"A\" * 80 + \"\\\"}\")\n\n    with patch(\"browsers.d2pfx.data.requests.get\", side_effect=RuntimeError(\"offline\")):\n        assert manager.fetch_gz_json(\"mods.json.gz\") is None\n''', encoding="utf-8")
